def check_case_a():
    count = 0
    # y=1. Condition: (x+1) / (x^z + 1) must be an integer.
    for x in range(1, 100):
        for z in range(1, 100):
            numerator = x + 1
            denominator = x**z + 1
            if numerator % denominator == 0:
                count += 1
    return count

def check_case_b():
    count = 0
    # z=1. Condition: (x+1)^y / (x+1) = (x+1)^(y-1) must be an integer.
    # Since x>=1, y>=1, this is always true.
    for x in range(1, 100):
        for y in range(1, 100):
            # We established this is always true.
            count += 1
    return count

count_a = check_case_a()
